// Type-checks src/ipc.rs (exported by ts-rs into ./generated by
// `cargo test`, see ipc::tests) against upstream's own ipc/types.ts.
// Each `const` below fails to compile naming the offending event(s); run
// `cargo test rust_ipc_types` to regenerate and re-check.
import type { IpcEvent, HostState } from '../vendor/awakened-poe-trade/ipc/types'
import type { ClientEvent } from './generated/ClientEvent'
import type { MainEvent } from './generated/MainEvent'
import type { HostState as OurHostState } from './generated/HostState'

type PayloadOf<E> = E extends { payload: infer P } ? P : undefined
type Named<U, N> = Extract<U, { name: N }>

type UpstreamIncoming = Extract<IpcEvent['name'], `CLIENT->MAIN::${string}` | `OVERLAY->MAIN::${string}`>
type Ok = 'ok'

// Every event the renderer can send is one ClientEvent parses (or knows
// to ignore)...
type Unhandled = Exclude<UpstreamIncoming, ClientEvent['name']>
export const unhandled: [Unhandled] extends [never] ? Ok : Unhandled = 'ok'
// ...and ClientEvent names no event upstream doesn't send.
type UnknownIncoming = Exclude<ClientEvent['name'], UpstreamIncoming>
export const unknownIncoming: [UnknownIncoming] extends [never] ? Ok : UnknownIncoming = 'ok'
// Whatever upstream sends fits our struct: our fields exist with our types.
type BadIncoming = {
  [N in ClientEvent['name']]: [PayloadOf<Named<IpcEvent, N>>] extends [PayloadOf<Named<ClientEvent, N>>] ? never : N
}[ClientEvent['name']]
export const badIncoming: [BadIncoming] extends [never] ? Ok : BadIncoming = 'ok'

// Everything we send exists upstream...
type UnknownOutgoing = Exclude<MainEvent['name'], IpcEvent['name']>
export const unknownOutgoing: [UnknownOutgoing] extends [never] ? Ok : UnknownOutgoing = 'ok'
// ...and has every field the renderer expects, with its type.
type BadOutgoing = {
  [N in MainEvent['name']]: [PayloadOf<Named<MainEvent, N>>] extends [PayloadOf<Named<IpcEvent, N>>] ? never : N
}[MainEvent['name']]
export const badOutgoing: [BadOutgoing] extends [never] ? Ok : BadOutgoing = 'ok'

// GET /config's body.
export const hostState: HostState = null as unknown as OurHostState
